CREATE TABLE teams (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, category TEXT NOT NULL, group_name TEXT NOT NULL, level TEXT NOT NULL DEFAULT '', gender TEXT NOT NULL DEFAULT 'mixed', fff_id TEXT, photo_key TEXT, description TEXT NOT NULL DEFAULT '', display_order INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_teams_group_active_order ON teams(group_name,active,display_order);
CREATE TABLE training_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, team_id INTEGER REFERENCES teams(id) ON DELETE CASCADE, category TEXT NOT NULL, weekday INTEGER NOT NULL CHECK(weekday BETWEEN 1 AND 7), starts_at TEXT NOT NULL, ends_at TEXT NOT NULL, venue TEXT NOT NULL, address TEXT NOT NULL DEFAULT '', notes TEXT NOT NULL DEFAULT '', active INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_training_weekday_active ON training_sessions(weekday,active);
CREATE TABLE contacts (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL, role TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'club', email TEXT, phone TEXT, published INTEGER NOT NULL DEFAULT 1, display_order INTEGER NOT NULL DEFAULT 0, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_contacts_published_order ON contacts(published,display_order);
CREATE TABLE tournaments (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, name TEXT NOT NULL, summary TEXT NOT NULL DEFAULT '', starts_on TEXT NOT NULL, ends_on TEXT, venue TEXT NOT NULL DEFAULT '', categories TEXT NOT NULL DEFAULT '[]', registration_url TEXT, rules_key TEXT, status TEXT NOT NULL DEFAULT 'draft', updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_tournaments_status_date ON tournaments(status,starts_on);
CREATE TABLE matches (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, source_id TEXT NOT NULL, category TEXT NOT NULL DEFAULT '', competition TEXT NOT NULL DEFAULT '', starts_at TEXT NOT NULL, venue TEXT NOT NULL DEFAULT '', home_team TEXT NOT NULL, away_team TEXT NOT NULL, home_score INTEGER, away_score INTEGER, status TEXT NOT NULL DEFAULT 'scheduled', raw_json TEXT NOT NULL DEFAULT '{}', synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(source,source_id));
CREATE INDEX idx_matches_date_status ON matches(starts_at,status);
CREATE TABLE social_posts (id INTEGER PRIMARY KEY AUTOINCREMENT, platform TEXT NOT NULL, source_id TEXT NOT NULL, permalink TEXT NOT NULL, caption TEXT NOT NULL DEFAULT '', media_type TEXT NOT NULL DEFAULT 'IMAGE', media_url TEXT, thumbnail_url TEXT, published_at TEXT NOT NULL, synced_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(platform,source_id));
CREATE INDEX idx_social_date ON social_posts(platform,published_at DESC);
CREATE TABLE documents (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, title TEXT NOT NULL, kind TEXT NOT NULL, object_key TEXT NOT NULL, published INTEGER NOT NULL DEFAULT 1, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sync_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, source TEXT NOT NULL, started_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, finished_at TEXT, status TEXT NOT NULL DEFAULT 'running', imported_count INTEGER NOT NULL DEFAULT 0, error_message TEXT);
